	'messages:apihelp-query+revisions-param-tag' => 'en:Only list revisions tagged with this tag.',
	'messages:apihelp-query+revisions-example-content' => 'en:Get data with content for the last revision of titles <kbd>API</kbd> and [[{{MediaWiki:Mainpage}}]].',
	'messages:apihelp-query+revisions-example-last5' => 'en:Get last 5 revisions of the [[{{MediaWiki:Mainpage}}]].',
